const acceptedAt = toIsoTimestamp(new Date());
const existing = await memberRepo.findMember(invitation.orgId, userId);

// A current member accepting an invite changes nothing about them. The
// token is still spent, so it cannot be reused.
if (existing && memberRepo.isCurrentMember(existing)) {
  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );
  return existing;
}

const member = existing
  ? await memberRepo.reinstateMember(
      invitation.orgId,
      existing.id,
      invitation.role,
      invitation.invitedBy,
      acceptedAt,
    )
  : await memberRepo.insertMember(
      invitation.orgId,
      userId,
      invitation.role,
      invitation.invitedBy,
    );

if (existing && !isArchived(existing) && existing.status === "active") {
  throw new Error("Membership was already active");
}

await invitationRepo.markInvitationAccepted(
